/* Enforce hidden attribute */
[hidden] {
  display: none !important;
}

:root {
  --bg-color: #2b2b38;
  --card-bg: #403f56;
  --accent-primary: #8bd450;
  --accent-warm: #f2884b;
  --text-main: #fbf9f5;
  --text-dim: #b6b4cc;
  --shadow-dark: #1e1e26;
  --tea-color: #8bd450;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  background-color: var(--bg-color);
  background-image:
    linear-gradient(45deg, #262633 25%, transparent 25%),
    linear-gradient(-45deg, #262633 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, #262633 75%),
    linear-gradient(-45deg, transparent 75%, #262633 75%);
  background-size: 32px 32px;
  background-position: 0 0, 0 16px, 16px -16px, -16px 0px;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 16px;
  font-family: 'Courier New', Courier, monospace, system-ui;
  font-size: 16px;
  color: var(--text-main);
}

.card {
  background: var(--card-bg);
  border: 4px solid var(--text-main);
  box-shadow: 8px 8px 0 var(--shadow-dark);
  width: 100%;
  max-width: 420px;
  padding: 28px 24px;
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 20px;
}

.header {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.title {
  font-size: 1.5rem;
  letter-spacing: 2px;
  text-shadow: 2px 2px 0 var(--shadow-dark);
}

.subtitle {
  font-size: 1rem;
  color: var(--text-dim);
}

/* Pixel Art Teacup */
.art-container {
  position: relative;
  width: 120px;
  height: 90px;
  margin: 4px auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-end;
}

.steam-group {
  position: absolute;
  top: 0;
  display: flex;
  gap: 14px;
}

.steam {
  width: 6px;
  height: 14px;
  background: var(--text-dim);
  border-radius: 2px;
  opacity: 0.6;
  animation: steamDrift 1.6s infinite steps(4);
}

.steam.s2 {
  animation-delay: 0.5s;
  height: 18px;
}

.steam.s3 {
  animation-delay: 1s;
}

@keyframes steamDrift {
  0% { transform: translateY(0); opacity: 0.7; }
  50% { transform: translateY(-6px); opacity: 0.3; }
  100% { transform: translateY(-12px); opacity: 0; }
}

.pixel-mug {
  position: relative;
  display: flex;
  align-items: center;
}

.mug-body {
  width: 68px;
  height: 52px;
  background: var(--text-main);
  border: 4px solid var(--shadow-dark);
  position: relative;
  box-shadow: inset -4px -4px 0 rgba(0,0,0,0.15);
}

.tea-liquid {
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  height: 38px;
  background: var(--tea-color);
  border-top: 4px solid var(--shadow-dark);
  transition: background-color 0.25s ease;
}

.tea-tag {
  position: absolute;
  top: 4px;
  right: -8px;
  width: 10px;
  height: 14px;
  background: var(--accent-warm);
  border: 2px solid var(--shadow-dark);
}

.mug-handle {
  width: 18px;
  height: 28px;
  border: 4px solid var(--shadow-dark);
  border-left: none;
  background: transparent;
}

.mug-saucer {
  width: 96px;
  height: 8px;
  background: var(--text-main);
  border: 3px solid var(--shadow-dark);
  margin-top: -2px;
}

/* Preset buttons */
.presets {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 10px;
  width: 100%;
}

.btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: bold;
  border: 3px solid var(--text-main);
  box-shadow: 4px 4px 0 var(--shadow-dark);
  cursor: pointer;
  background: var(--card-bg);
  color: var(--text-main);
  padding: 10px 14px;
  text-align: center;
  user-select: none;
  outline: none;
  transition: transform 0.05s, box-shadow 0.05s;
}

.btn:hover:not(:disabled) {
  transform: translate(-1px, -1px);
  box-shadow: 5px 5px 0 var(--shadow-dark);
}

.btn:active:not(:disabled) {
  transform: translate(3px, 3px);
  box-shadow: 1px 1px 0 var(--shadow-dark);
}

.btn:focus-visible {
  outline: 3px dashed var(--accent-primary);
  outline-offset: 3px;
}

.preset-btn {
  flex: 1 1 95px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}

.preset-time {
  font-size: 0.85rem;
  color: var(--text-dim);
}

.preset-btn.active {
  background: var(--accent-primary);
  color: var(--shadow-dark);
  border-color: var(--text-main);
  box-shadow: 2px 2px 0 var(--shadow-dark);
  transform: translate(2px, 2px);
}

.preset-btn.active .preset-time {
  color: #1e1e26;
  font-weight: 900;
}

/* Display and Messages */
.timer-display-wrap {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  width: 100%;
  background: #1e1e26;
  border: 4px solid var(--text-main);
  padding: 16px 10px;
  box-shadow: inset 3px 3px 0 rgba(0, 0, 0, 0.4);
}

.timer-display {
  font-size: 3rem;
  font-weight: bold;
  letter-spacing: 4px;
  color: var(--accent-primary);
  line-height: 1;
}

.message {
  font-size: 1.15rem;
  font-weight: bold;
  color: var(--accent-warm);
  text-transform: uppercase;
  letter-spacing: 1px;
  animation: blink 0.8s infinite steps(2);
}

@keyframes blink {
  50% { opacity: 0; }
}

/* Controls */
.controls {
  display: flex;
  justify-content: center;
  gap: 16px;
  width: 100%;
}

.control-btn {
  flex: 1;
  padding: 12px 18px;
  font-size: 1.15rem;
}

.start-btn {
  background: var(--accent-primary);
  color: var(--shadow-dark);
}

.cancel-btn {
  background: var(--accent-warm);
  color: var(--shadow-dark);
}

.btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
  box-shadow: none;
  transform: none;
}

@media (max-width: 360px) {
  .card {
    padding: 16px 12px;
  }
  .timer-display {
    font-size: 2.4rem;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  const timerDisplay = document.getElementById('timerDisplay');
  const statusMessage = document.getElementById('statusMessage');
  const startBtn = document.getElementById('startBtn');
  const cancelBtn = document.getElementById('cancelBtn');
  const presetButtons = document.querySelectorAll('.preset-btn');
  const teaLiquid = document.getElementById('teaLiquid');

  const TEA_COLORS = {
    Green: '#8bd450',
    Black: '#9c4c23',
    Herbal: '#e85d75'
  };

  let selectedDuration = 120;
  let remainingSeconds = 120;
  let currentTeaName = 'Green';
  let timerInterval = null;
  let isRunning = false;

  function formatTime(totalSeconds) {
    const minutes = Math.floor(totalSeconds / 60);
    const seconds = totalSeconds % 60;
    const paddedSeconds = seconds < 10 ? '0' + seconds : seconds;
    return `${minutes}:${paddedSeconds}`;
  }

  function updateDisplay() {
    timerDisplay.textContent = formatTime(remainingSeconds);
  }

  function selectPreset(button) {
    if (isRunning) return;

    presetButtons.forEach(btn => {
      btn.classList.remove('active');
      btn.setAttribute('aria-pressed', 'false');
    });

    button.classList.add('active');
    button.setAttribute('aria-pressed', 'true');

    selectedDuration = parseInt(button.dataset.time, 10);
    remainingSeconds = selectedDuration;
    currentTeaName = button.dataset.name;

    if (TEA_COLORS[currentTeaName] && teaLiquid) {
      teaLiquid.style.backgroundColor = TEA_COLORS[currentTeaName];
    }

    statusMessage.hidden = true;
    updateDisplay();
  }

  function startTimer() {
    if (isRunning) return;

    if (remainingSeconds <= 0) {
      remainingSeconds = selectedDuration;
    }

    isRunning = true;
    startBtn.disabled = true;
    cancelBtn.disabled = false;
    presetButtons.forEach(btn => (btn.disabled = true));
    statusMessage.hidden = true;

    const targetTimestamp = Date.now() + remainingSeconds * 1000;

    timerInterval = setInterval(() => {
      const now = Date.now();
      const diffSeconds = Math.round((targetTimestamp - now) / 1000);

      if (diffSeconds <= 0) {
        remainingSeconds = 0;
        updateDisplay();
        finishTimer();
      } else {
        remainingSeconds = diffSeconds;
        updateDisplay();
      }
    }, 200);
  }

  function finishTimer() {
    clearInterval(timerInterval);
    timerInterval = null;
    isRunning = false;
    startBtn.disabled = false;
    cancelBtn.disabled = true;
    presetButtons.forEach(btn => (btn.disabled = false));
    statusMessage.hidden = false;
  }

  function cancelTimer() {
    if (timerInterval) {
      clearInterval(timerInterval);
      timerInterval = null;
    }
    isRunning = false;
    remainingSeconds = selectedDuration;
    updateDisplay();
    startBtn.disabled = false;
    cancelBtn.disabled = true;
    presetButtons.forEach(btn => (btn.disabled = false));
    statusMessage.hidden = true;
  }

  presetButtons.forEach(button => {
    button.addEventListener('click', () => selectPreset(button));
  });

  startBtn.addEventListener('click', startTimer);
  cancelBtn.addEventListener('click', cancelTimer);

  // Initialize
  updateDisplay();
});
